import unittest.mock

from _pytest.compat import getfuncargnames, num_mock_patch_args


class AmbiguousArray(object):
    """Mimics the NumPy truth-value behavior that caused the issue."""

    def __eq__(self, other):
        return self

    def __ne__(self, other):
        return self

    def __bool__(self):
        raise ValueError(
            "The truth value of an array with more than one element is ambiguous"
        )


array = AmbiguousArray()
try:
    array in [unittest.mock.DEFAULT]
except ValueError as exc:
    print("old membership check reproduced ValueError: {}".format(exc))
else:
    raise AssertionError("old membership check should have failed")


@unittest.mock.patch("os.getcwd", new=AmbiguousArray())
def patched_with_array(x, y):
    pass


@unittest.mock.patch("os.getcwd")
def patched_with_default(mock_getcwd, x, y):
    pass


assert num_mock_patch_args(patched_with_array) == 0
assert getfuncargnames(patched_with_array) == ("x", "y")
assert num_mock_patch_args(patched_with_default) == 1
assert getfuncargnames(patched_with_default) == ("x", "y")
print("fixed helper results: array=0, default=1; argument names preserved")
